WITH flattened_attrs AS (SELECT id, created_at, coupon_codes, items, SIZE(FILTER(items, i -> i.qty >= 3)) AS bulk_lines, attributes['utm_source'] AS utm_source, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, TRANSFORM(items, i -> i.product_id) AS product_ids, attributes['device'] AS device FROM carts WHERE SIZE(coupon_codes) >= 2) SELECT id, coupons_text, COUNT(bulk_lines) OVER w_recent AS running_count_bulk_lines, SUM(bulk_lines) OVER w_recent AS running_sum_bulk_lines, MAX(bulk_lines) OVER w_recent AS running_max_bulk_lines FROM flattened_attrs WINDOW w_recent AS (ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
